<script setup>
import {ref,computed,watch,onUnmounted} from 'vue';
import BaseModal from '../components/BaseModal.vue';import Icon from '../components/Icon.vue';
import {state,company,api,scope,notify,changed,activate,can,moduleNames} from '../lib/workspace';
import {dateTime} from '../lib/format';
const props=defineProps({module:{type:String,default:'fiscal'}});
const year=ref(Number(state.period.slice(0,4))),newYear=ref(new Date().getFullYear()+1),data=ref({years:[],months:[]}),history=ref([]),loading=ref(false),error=ref(''),show=ref(false),selected=ref(null),reason=ref(''),busy=ref(false),context=ref({});let seq=0,ownedEditor=null;
// Disable synchronously for the whole activation, not only its later calendar reload.
const interactionBlocked=computed(()=>loading.value||busy.value||state.contextBusy||!!state.editor||!!state.confirm);
function claimEditor(name){state.editor={name,companyId:state.companyId};ownedEditor=state.editor;}
function releaseEditor(){if(ownedEditor&&state.editor===ownedEditor)state.editor=null;ownedEditor=null;}
const months=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
async function load(){if(!state.companyId)return;const n=++seq;loading.value=true;error.value='';try{const [d,h]=await Promise.all([api(scope(`/exercises?module=${props.module}&year=${year.value}`)),api(scope(`/exercises/history?module=${props.module}&year=${year.value}`))]);if(n===seq){data.value=d;history.value=h;}}catch(e){if(n===seq)error.value=e.message;}finally{if(n===seq)loading.value=false;}}
watch(()=>[state.companyId,state.refresh,props.module],()=>{year.value=Number(state.period.slice(0,4));load();},{immediate:true});watch(year,load);
async function create(){if(interactionBlocked.value)return;busy.value=true;claimEditor('Cadastro de exercício');error.value='';try{await api(scope('/exercises'),{method:'POST',body:{year:Number(newYear.value),module:props.module}});year.value=Number(newYear.value);await load();notify('Exercício cadastrado com os doze meses disponíveis.');}catch(e){error.value=e.message;}finally{busy.value=false;releaseEditor();}}
async function select(m){if(interactionBlocked.value||!m.enabled)return;try{if(await activate(state.companyId,m.period,props.module))notify(`Competência ${m.period.split('-').reverse().join('/')} selecionada para ${moduleNames[props.module]}.`);}catch(e){notify(e.message,'error');}}
function open(m){if(interactionBlocked.value||!m.enabled)return;selected.value={...m};reason.value='';error.value='';context.value={id:state.companyId,name:company.value.name,module:props.module};show.value=true;claimEditor('Situação da competência');}
function close(){if(!busy.value){show.value=false;releaseEditor();}}
async function save(){if(busy.value||state.contextBusy||!show.value||!selected.value||!reason.value.trim())return;busy.value=true;error.value='';try{const m=selected.value;await api(scope('/periods/'+(m.closed?'reopen':'close'),context.value.id),{method:'POST',body:{module:context.value.module,period:m.period,version:m.version,reason:reason.value}});show.value=false;changed();await load();notify('Situação da competência atualizada e auditada.');}catch(e){error.value=e.message;}finally{busy.value=false;if(!show.value)releaseEditor();}}
onUnmounted(()=>{seq++;releaseEditor();});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">{{company?.code}} · {{company?.name}}</div><h1>Competências · {{moduleNames[module]}}</h1><p>Cadastrar um exercício disponibiliza os doze meses. Selecionar um mês não altera seu bloqueio.</p></div><span class="badge neutral">Ativa: {{state.period.split('-').reverse().join('/')}}</span></header>
<p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="module==='social'" class="message subtle">O módulo Social possui controle de exercícios e competências. Rotinas de folha, encargos e obrigações ainda precisam de especificação; este calendário não executa nem declara essas obrigações.</p>
<section class="panel"><div class="panel-heading"><label>Exercício<select v-model.number="year" :disabled="interactionBlocked" aria-label="Exercício do módulo"><option v-if="!data.years.some(y=>y.year===year)" :value="year">{{year}} · não cadastrado</option><option v-for="y in data.years" :key="y.year" :value="y.year">{{y.year}}</option></select></label><form v-if="can(module+'.periods','create')" class="actions" @submit.prevent="create"><label>Novo exercício<input v-model.number="newYear" type="number" min="1900" max="2199" required :disabled="interactionBlocked" aria-label="Ano do novo exercício"/></label><button class="button primary" :disabled="interactionBlocked">Cadastrar exercício</button></form></div>
<div class="month-grid"><article v-for="(m,i) in data.months" :key="m.period" class="month-card" :class="{active:m.period===state.period,blocked:m.closed}"><div class="split"><h2>{{months[i]}}</h2><span class="badge" :class="!m.enabled?'neutral':m.closed?'warning':'success'">{{!m.enabled?'Não cadastrado':m.closed?'Bloqueada':'Aberta'}}</span></div><p>{{m.period.split('-').reverse().join('/')}}</p><small v-if="m.changed_at">{{m.actor}} · {{dateTime(m.changed_at)}}</small><p class="period-reason">{{m.reason||'Sem fechamento registrado.'}}</p><div class="actions"><button class="button small" :disabled="!m.enabled||interactionBlocked" @click="select(m)">{{m.period===state.period?'Selecionada':'Selecionar / consultar'}}</button><button v-if="can(module+'.periods',m.closed?'reopen':'close')" class="button small outline" :disabled="!m.enabled||interactionBlocked" @click="open(m)">{{m.closed?'Reabrir':'Fechar'}}</button></div></article></div></section>
<p class="message subtle">O bloqueio vale somente para esta empresa, este módulo e este mês. Competências bloqueadas continuam disponíveis para consulta. Operações integradas verificam também os módulos atingidos.</p>
<section class="panel"><div class="panel-heading"><h2>Histórico do exercício</h2><small>Até 500 eventos, com responsável e justificativa</small></div><div class="table-scroll"><table><thead><tr><th>Competência</th><th>Ação</th><th>Responsável</th><th>Data</th><th>Justificativa</th></tr></thead><tbody><tr v-for="h in history" :key="h.id"><td>{{h.entity_id.split(':')[0]}}</td><td>{{h.action==='close'?'Fechamento':'Reabertura'}}</td><td>{{h.actor}}</td><td>{{dateTime(h.created_at)}}</td><td>{{h.details.reason}}</td></tr><tr v-if="!history.length"><td colspan="5">Nenhuma alteração registrada neste exercício.</td></tr></tbody></table></div></section>
<BaseModal v-if="show" :title="selected.closed?'Reabrir competência':'Fechar competência'" :subtitle="`${context.name} · ${moduleNames[context.module]} · ${selected.period}`" @close="close"><form id="period-form" @submit.prevent="save"><p v-if="error" class="message error">{{error}}</p><label>Justificativa *<textarea v-model="reason" rows="4" maxlength="1000" required autofocus/></label><p>Os demais módulos e competências mantêm suas situações.</p></form><template #footer><button class="button" @click="close" :disabled="busy">Cancelar</button><button class="button primary" form="period-form" :disabled="busy||!reason.trim()">{{selected.closed?'Confirmar reabertura':'Confirmar fechamento'}}</button></template></BaseModal></div></template>
<style scoped>.month-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:16px}.month-card{border:1px solid #dce3e7;border-radius:8px;padding:14px;min-width:0}.month-card.active{border-color:#28776a;background:#f4faf8}.month-card.blocked{border-left:4px solid #bc8c31}.month-card h2{font-size:15px;margin:0}.period-reason{font-size:12px;overflow-wrap:anywhere;color:#61717c;min-height:28px}.month-card .actions{flex-wrap:wrap}.month-card small{font-size:11px}.panel-heading form{align-items:end}@media(max-width:1100px){.month-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.month-grid{grid-template-columns:1fr}.panel-heading{flex-wrap:wrap}}</style>
